def copy_authors_to_contributors(apps, schema_editor):
    """Eski `book.authors` bog'lanishlarini `Contributor` yozuvlariga ko'chiradi."""
    Book = apps.get_model('book_app', 'Book')
    Contributor = apps.get_model('book_app', 'Contributor')

    rows = []
    for book in Book.objects.prefetch_related('authors').all():
        for order, author in enumerate(book.authors.all()):
            rows.append(Contributor(book=book, author=author, role='AUTHOR', order=order))
    if rows:
        Contributor.objects.bulk_create(rows, ignore_conflicts=True)
    print(f"  {len(rows)} ta muallif bog'lanishi Contributor'ga ko'chirildi")


def restore_authors_m2m(apps, schema_editor):
    """Orqaga qaytarishda bog'lanishlar eski M2M jadvaliga tiklanadi."""
    Book = apps.get_model('book_app', 'Book')
    Contributor = apps.get_model('book_app', 'Contributor')
    for contributor in Contributor.objects.filter(role='AUTHOR').select_related('book', 'author'):
        Book.objects.get(pk=contributor.book_id).authors.add(contributor.author)


